const body = $input.first().json.body;
const data = body?.data || {};

if (!data || (!data.body && !data.media)) {
  return [{ json: { hasMessage: false } }];
}

const media = data.media || null;

return [{
  json: {
    hasMessage: true,
    from: data.fromNumber || data.from || '',
    contactName: data.chat?.contact?.name || data.chat?.name || '',
    messageType: media ? 'attachment' : 'text',
    textBody: data.body || media?.caption || '',
    mimeType: media?.mime || media?.mimetype || media?.mimeType || null,
    filename: media?.filename || null,
    messageId: data.id || null,
    deviceId: body?.device?.id || null,
    chatId: data.chat?.id || null
  }
}];

// Parse and normalize the client/document extraction JSON from the OpenAI node's reply.
// Handles the several possible output shapes the langchain OpenAI node can return.

const input = $input.first().json;

let raw =
  input.output?.[0]?.content?.find(part => part?.type === 'output_text' || part?.type === 'text')?.text ??
  input.output?.[0]?.content?.[0]?.text ??
  input.choices?.[0]?.message?.content ??
  input.output_text ??
  input.text ??
  input.message?.content ??
  input.content ??
  '';

if (typeof raw === 'object' && raw !== null) raw = JSON.stringify(raw);
raw = String(raw || '').trim();
const originalRaw = raw;

raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) raw = raw.slice(firstBrace, lastBrace + 1);

let parsed = null;
let parseError = null;
let parseRepaired = false;

try {
  parsed = JSON.parse(raw);
} catch (firstError) {
  parseError = firstError.message;
  let repaired = raw
    .replace(/(:\s*)(\d{4}-\d{2}-\d{2})(?=\s*[,}\]])/g, '$1"$2"')
    .replace(/,\s*([}\]])/g, '$1')
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u2018\u2019]/g, "'");
  try {
    parsed = JSON.parse(repaired);
    parseRepaired = true;
    parseError = null;
    raw = repaired;
  } catch (secondError) {
    parseError = `Initial parse error: ${firstError.message}. Repair parse error: ${secondError.message}`;
  }
}

if (!parsed || typeof parsed !== 'object') {
  parsed = { client_name: null, company_or_organization: null, document_type: null, document_date: null, amount: null, currency: null, summary: null };
  parseError = parseError || 'The AI response could not be parsed.';
}

let amount = parsed.amount;
if (typeof amount === 'string') {
  const cleaned = amount.replace(/[^0-9.\-]/g, '');
  amount = cleaned ? Number(cleaned) : null;
}
if (typeof amount !== 'number' || Number.isNaN(amount)) amount = null;

const msg = $('Extract Message2').first().json || {};

return [{
  json: {
    received_at: new Date().toISOString(),
    whatsapp_from: msg.from ?? '',
    contact_name: msg.contactName ?? '',
    filename: msg.filename ?? '',
    mime_type: msg.mimeType ?? '',
    caption_text: msg.textBody ?? '',
    client_name: parsed.client_name ?? '',
    company_or_organization: parsed.company_or_organization ?? '',
    document_type: parsed.document_type ?? 'Other',
    document_date: parsed.document_date ?? null,
    amount: amount ?? 0,
    currency: parsed.currency ?? '',
    summary: parsed.summary ?? '',
    parse_success: parseError === null,
    parse_repaired: parseRepaired,
    parse_error: parseError,
    raw_ai_response: parseError ? originalRaw : '',
    extracted_document: parsed,
  },
}];

