// Merge the classified instruction with the last saved document for this contact.
const classify = $('Parse Classification Result2').first().json;
const page = $input.first().json || {};

// Actual Notion "getAll" output shape for this node/version: flattened,
// snake_case, prefixed with "property_" (confirmed from live output):
//   property_patient_name, property_hospital_name_clinic_name,
//   property_total_bill_amount, property_date_of_visit
// Also keep a couple of fallbacks in case the node version/shape changes.
const props = page.property || page.properties || page;

const lastClientName = props.property_patient_name || props.name || props['Patient Name']
  || props.patient_name || classify.recipientName || classify.contactName
  || classify.contact_name || 'the client';
const lastCompany   = props.property_hospital_name_clinic_name || props['Hospital Name/Clinic Name']
  || props.company_or_organization || '';
const lastDocType   = props.property_document_type || props['Document Type'] || '';
const lastAmount    = props.property_total_bill_amount || props['Total bill Amount']
  || props.amount || '';
const lastCurrency  = props.property_currency || props['Currency'] || '';
const lastDocDate   = props.property_date_of_visit?.start || props.property_date_of_visit
  || props['Date of Visit'] || props.document_date || '';
const lastSummary   = props.property_document_summary || props['Document Summary'] || props.summary
  || (lastClientName !== 'the client'
        ? `Invoice on file for ${lastClientName}${lastCompany ? ' at ' + lastCompany : ''}${lastAmount ? ', total bill amount ' + lastAmount : ''}${lastDocDate ? ' dated ' + lastDocDate : ''}.`
        : 'No saved document was found for this contact yet.');

return [{
  json: {
    ...classify,
    lastClientName,
    lastCompany,
    lastDocType,
    lastSummary,
    lastAmount,
    lastCurrency,
    lastDocDate,
  },
}];

// Check whether Wassenger has finished processing the media and produced a download link.
const msg = $input.first().json;
const media = msg.media || {};
const downloadPath = media?.links?.download;
const orig = $('Extract Message2').first().json;

let retryCount = 0;
try {
  retryCount = $input.first().json.retryCount ?? orig.retryCount ?? 0;
} catch (e) {
  retryCount = 0;
}

if (downloadPath) {
  return [{ json: { ...orig, mediaUrl: `https://api.wassenger.com${downloadPath}`, mediaReady: true, retryCount } }];
}

return [{ json: { ...orig, mediaReady: false, retryCount: retryCount + 1 } }];

const basePrompt = `You are a document extraction engine. Look at the main, frontmost document and extract:

1. client_name - the name of the person/client the document is about or addressed to.
2. company_or_organization - the company, hospital, clinic, vendor, or organization that issued the document.
3. document_type - one of: Invoice, Receipt, Bill, ID, Contract, Form, Other.
4. document_date - the main relevant date (visit, invoice, or issue date), normalized to YYYY-MM-DD if possible.
5. amount - the total amount on the document as a plain number (no currency symbols/commas), or null if not applicable.
6. currency - a 3-letter currency code or symbol if visible, otherwise null.
7. summary - a 1-2 sentence plain-language summary of what this document is.

RULES:
- Use null for any field that cannot genuinely be found. Do not guess.
- amount must be a JSON number (not a string), or null.
- Return only valid JSON, no markdown or code fences.

Return exactly this JSON structure:
{
  "client_name": null,
  "company_or_organization": null,
  "document_type": null,
  "document_date": null,
  "amount": null,
  "currency": null,
  "summary": null
}`;

// Image branch: build a base64 data URL for the langchain OpenAI node's image input
const extractedMessage = $('Extract Message2').first().json || {};
let mimeType = String(extractedMessage.mimeType || '').trim().toLowerCase();
let filename = String(extractedMessage.filename || '').trim();

const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('No binary file was found in the input item.');
}
const binaryPropertyName = binaryKeys[0];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryPropertyName);
if (!buffer || buffer.length === 0) {
  throw new Error('The downloaded file is empty.');
}
const base64 = buffer.toString('base64');

if (!mimeType) {
  const extension = filename.split('.').pop()?.toLowerCase();
  const mimeMap = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif' };
  mimeType = mimeMap[extension] || 'image/jpeg';
}
if (!filename) filename = mimeType === 'image/png' ? 'document.png' : 'document.jpg';

return [{
  json: {
    prompt: basePrompt,
    imageDataUrl: `data:${mimeType};base64,${base64}`,
    attachmentType: 'image',
    mimeType,
    filename
  }
}];

const basePrompt = `You are a document extraction engine. Look at the main, frontmost document and extract:

1. client_name - the name of the person/client the document is about or addressed to.
