// PDF/Doc branch: text was already pulled out upstream by "Extract Text (PDF/Doc)"
const extractedMessage = $('Extract Message2').first().json || {};
const extractedText = $json.text || $json.data || '';

return [{
  json: {
    prompt: basePrompt + `\n\nHere is the extracted document text:\n\n${extractedText}`,
    imageDataUrl: null,
    attachmentType: (extractedMessage.mimeType || '').includes('pdf') ? 'pdf' : 'doc',
    mimeType: extractedMessage.mimeType || '',
    filename: extractedMessage.filename || ''
  }
}];

// Build a prompt for GPT to draft a professional, internal, company-facing email.
// This email goes to a COMPANY address (given by the client in the WhatsApp
// message), never to the end customer directly.

const p = $json;

const contextParts = [];
if (p.lastClientName && p.lastClientName !== 'the client') contextParts.push(`Recipient/client name to use in the greeting: ${p.lastClientName}`);
if (p.lastCompany) contextParts.push(`Company: ${p.lastCompany}`);
if (p.lastDocType) contextParts.push(`Document type: ${p.lastDocType}`);
if (p.lastDocDate) contextParts.push(`Document date: ${p.lastDocDate}`);
if (p.lastAmount) contextParts.push(`Amount: ${p.lastAmount} ${p.lastCurrency || ''}`);
if (p.lastSummary) contextParts.push(`Last saved document summary: ${p.lastSummary}`);

const referenceInfo = contextParts.length
  ? contextParts.join('\n')
  : 'No saved document is on file for this contact yet — do not invent one.';

const instruction = p.emailContext || p.taskDescription || '';

// Category-specific guidance. The recipient address is always whatever the
// client provided — categories only change tone/structure, not routing.
const categoryGuidance = {
  'Credit Card Issue':
    'This is about a credit card / payment / transaction problem. Be precise and factual about the issue described. ' +
    'Do NOT invent card numbers, transaction IDs, or amounts that were not given to you — ask the recipient to verify against internal records if specifics are missing. Keep a calm, matter-of-fact tone appropriate for a payments team.',
  'Client Issue':
    'This is a client complaint or problem that needs internal attention. Use an empathetic but professional tone, clearly state what the client reported, and make the urgency/impact clear so the reader understands why it needs prompt attention.',
  'Invoice Info':
    'This is about invoice/billing information. Reference the specific invoice details provided (amount, date, document type) accurately. Be concise and businesslike — this is a routine informational or follow-up email.',
  'General':
    'No specific category was given — write a clear, professional email based on the instruction and reference information below.'
};
const guidance = categoryGuidance[p.emailCategory] || categoryGuidance['General'];

const prompt = `You are drafting a professional, internal business email on behalf of ${p.contactName || 'a team member'}. This email is ALWAYS sent to a colleague or department inside our own company (e.g. billing, support, accounts) about a client's situation — it is NEVER sent to the client/customer themselves. Write it the way a staff member would write to a coworker: clear, courteous, and to the point, with enough client context that the reader immediately understands who this is about and what's needed from them.

Email category: ${p.emailCategory || 'General'}
${guidance}

Instruction received over WhatsApp:
"${instruction}"

Reference information that may be relevant (use only what actually helps; ignore what doesn't):
${referenceInfo}

Write a concise, professional email that fulfils the instruction above. Return ONLY valid JSON, with no markdown formatting and no code fences, in exactly this shape:
{"subject": "...", "body": "..."}

Rules:
- "body" is plain text (no markdown), opens with an appropriate greeting, and closes with a professional sign-off.
- Do not invent facts, amounts, dates, or names that are not present in the instruction or the reference information.
- Keep it focused and no longer than necessary to convey the request clearly.
- Open the body by clearly identifying the client and, briefly, their situation (e.g. "I'm reaching out regarding [client], who is experiencing [issue].") before making the request — the reader should not have to guess who this is about.
- If a recipient/client name is given above, use it in the greeting (e.g. "Hello John,"). If no name is given, use a generic greeting (e.g. "Hello," or "Hi team,") — never write a placeholder like "[Recipient's Name]" or "[Client Name]".`;

return [{ json: { ...p, emailPrompt: prompt } }];

// Robustly parse the {subject, body} JSON returned by "Generate Email Content".
const input = $input.first().json;

let raw =
  input.output?.[0]?.content?.find(part => part?.type === 'output_text' || part?.type === 'text')?.text ??
  input.output?.[0]?.content?.[0]?.text ??
  input.choices?.[0]?.message?.content ??
  input.output_text ??
  input.text ??
  input.message?.content ??
  input.content ??
  '';

if (typeof raw === 'object' && raw !== null) raw = JSON.stringify(raw);
raw = String(raw || '').trim();

raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) raw = raw.slice(firstBrace, lastBrace + 1);

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

const carry = $('Prepare Email Prompt2').first().json;

return [{
  json: {
    ...carry,
    emailSubject: (parsed && parsed.subject) || `Update regarding ${carry.lastClientName || carry.contactName || 'client'}`,
    emailBody: (parsed && parsed.body) || raw || carry.emailContext,
  },
}];

