// Robustly parse the intent-classification JSON from "Classify Intent (AI)".
const input = $input.first().json;

let raw =
  input.output?.[0]?.content?.find(part => part?.type === 'output_text' || part?.type === 'text')?.text ??
  input.output?.[0]?.content?.[0]?.text ??
  input.choices?.[0]?.message?.content ??
  input.output_text ??
  input.text ??
  input.message?.content ??
  input.content ??
  '';

if (typeof raw === 'object' && raw !== null) raw = JSON.stringify(raw);
raw = String(raw || '').trim();
raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) raw = raw.slice(firstBrace, lastBrace + 1);

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

const carry = $('Prepare Classification Prompt2').first().json;
const text = carry.rawText || carry.textBody || carry.caption_text || '';

// Fallback: if the model call or parse failed entirely, don't silently
// drop the message - mark it as a General Task so a human can still see it.
let taskType = (parsed && parsed.taskType) || (text ? 'General Task' : null);

// Normalize away the retired "Follow Up" category, in case an older cached
// prompt or a stale model response still returns it - treat it as Give Summary.
if (taskType === 'Follow Up') taskType = 'Give Summary';

const hasInstruction = parsed ? !!parsed.hasInstruction : (text.length > 0);

return [{
  json: {
    ...carry,
    hasInstruction,
    taskType: taskType || 'General Task',
    taskDescription: text,
    emailAddress: (parsed && parsed.emailAddress) || null,
    emailCategory: (parsed && parsed.emailCategory) || 'General',
    emailMode: (parsed && parsed.emailMode) || 'send',
    emailContext: (parsed && parsed.emailContext) || text,
    recipientName: (parsed && parsed.recipientName) || null,
  },
}];

// Reshape classified instruction data into the field names the
// Manual Meeting Scheduler's Execute Workflow Trigger expects.
// Handles both booking requests and named-client summary requests -
// the scheduler flow uses messageText to tell which one it is.
const j = $json;

return [{
  json: {
    ownerPhone: j.from || j.whatsapp_from || j.contact_name || '',
    messageText: j.taskDescription || j.rawText || j.textBody || '',
    recipientNameGuess: j.recipientName || j.contactName || j.contact_name || null,
  }
}];
